//! x86-64 SIMD basics: SSE..SSE4.1 (legacy encoding) and AVX/AVX2/FMA (VEX), xmm/ymm 0..15.
//! Hand-written table of the common integer/float ops; every op is byte-checked against LLVM
//! (`src/simd_tests.zig`, generated by scripts/gen_simd_tests.py). No EVEX (AVX-512) yet.
const std = @import("std");
const CodeBuffer = @import("../core/code_buffer.zig").CodeBuffer;
const x = @import("assembler.zig");
const Mem = x.Mem;

pub const Error = @import("../core/code_buffer.zig").Error || error{InvalidOperand};

/// Vector register: `xmm(i)` (128-bit) or `ymm(i)` (256-bit, VEX only).
pub const Vec = struct {
    id: u4,
    ymm: bool = false,
};
pub fn xmm(i: u4) Vec {
    return .{ .id = i };
}
pub fn ymm(i: u4) Vec {
    return .{ .id = i, .ymm = true };
}

pub const Feature = enum { sse, sse2, ssse3, sse41, avx, avx2, fma };

/// pp: 0 none, 1 = 66, 2 = F3, 3 = F2. map: 1 = 0F, 2 = 0F38, 3 = 0F3A.
pub const Op = struct {
    pp: u2,
    map: u2 = 1,
    op: u8,
    w: bool = false,
    sse: Feature,
    /// Feature of the VEX form; `avx2` for 256-bit integer ops is applied automatically.
    vex: Feature = .avx,
    int: bool = false,
    /// VEX: the r/m source is always xmm (broadcasts).
    src_xmm: bool = false,
    /// Two-operand op (moves, sqrt, broadcast): VEX.vvvv unused.
    two: bool = false,
    /// Scalar op (ss = 4, sd = 8 bytes in memory); xmm only.
    scalar: u8 = 0,
    /// Commutative: VEX swaps sources to reach the 2-byte C5 prefix (LLVM does the same).
    comm: bool = false,
};

pub const ops = struct {
    pub const movups: Op = .{ .two = true, .pp = 0, .op = 0x10, .sse = .sse };
    pub const movups_st: Op = .{ .two = true, .pp = 0, .op = 0x11, .sse = .sse };
    pub const movaps: Op = .{ .two = true, .pp = 0, .op = 0x28, .sse = .sse };
    pub const movaps_st: Op = .{ .two = true, .pp = 0, .op = 0x29, .sse = .sse };
    pub const movdqu: Op = .{ .two = true, .pp = 2, .op = 0x6f, .sse = .sse2 };
    pub const movdqu_st: Op = .{ .two = true, .pp = 2, .op = 0x7f, .sse = .sse2 };
    pub const movdqa: Op = .{ .two = true, .pp = 1, .op = 0x6f, .sse = .sse2 };
    pub const movdqa_st: Op = .{ .two = true, .pp = 1, .op = 0x7f, .sse = .sse2 };
    pub const addps: Op = .{ .comm = true, .pp = 0, .op = 0x58, .sse = .sse };
    pub const addpd: Op = .{ .comm = true, .pp = 1, .op = 0x58, .sse = .sse2 };
