pub const Rm = union(enum) { reg: Vec, mem: Mem };
pub fn r(v: Vec) Rm {
    return .{ .reg = v };
}
pub fn m(mem: Mem) Rm {
    return .{ .mem = mem };
}

/// Feature an encoding needs (for `cpu.host()` checks by the caller).
pub fn feature(comptime op: Op, is_vex: bool, wide: bool) Feature {
    if (!is_vex) return op.sse;
    if (wide and op.int) return .avx2;
    return op.vex;
}

const Buf = struct {
    b: [16]u8 = undefined,
    n: u8 = 0,
    fn put(s: *Buf, v: u8) void {
        s.b[s.n] = v;
        s.n += 1;
    }
};

fn rexBits(rm: Rm) struct { x: u1, b: u1 } {
    return switch (rm) {
        .reg => |v| .{ .x = 0, .b = @intCast(v.id >> 3) },
        .mem => |mm| .{ .x = if (mm.index) |i| @intCast(@backingInt(i) >> 3) else 0, .b = if (mm.base) |b| @intCast(@backingInt(b) >> 3) else 0 },
    };
}

fn modrm(o: *Buf, reg: u4, rm: Rm) Error!void {
    const rf: u8 = @as(u8, reg & 7) << 3;
    switch (rm) {
        .reg => |v| o.put(0xc0 | rf | (v.id & 7)),
        .mem => |mm| {
            if (mm.index == .rsp) return error.InvalidOperand;
            if (mm.base) |base| {
                const lo = @backingInt(base) & 7;
                const mod: u8 = if (mm.disp == 0 and lo != 5) 0 else if (std.math.cast(i8, mm.disp) != null) 0x40 else 0x80;
                if (mm.index != null or lo == 4) {
                    o.put(mod | rf | 4);
                    o.put(@as(u8, @backingInt(mm.scale)) << 6 | (if (mm.index) |i| @as(u8, @backingInt(i) & 7) else 4) << 3 | lo);
                } else o.put(mod | rf | lo);
                if (mod == 0x40) o.put(@bitCast(@as(i8, @intCast(mm.disp)))) else if (mod == 0x80) disp32(o, mm.disp);
            } else {
                o.put(rf | 4);
                o.put(@as(u8, @backingInt(mm.scale)) << 6 | (if (mm.index) |i| @as(u8, @backingInt(i) & 7) else 4) << 3 | 5);
                disp32(o, mm.disp);
            }
        },
    }
}

fn disp32(o: *Buf, d: i32) void {
    const u: u32 = @bitCast(d);
    for (0..4) |k| o.put(@truncate(u >> @intCast(k * 8)));
}

fn commit(cb: *CodeBuffer, o: *const Buf) Error!void {
    try cb.emitBytes(o.b[0..o.n]);
}

/// Legacy SSE: `op dst, src` (load direction). For `_st` ops pass the memory as `src` and the
/// register as `dst`: the encoding is the same ModRM, LLVM prints them as `op mem, reg`.
pub fn sse(cb: *CodeBuffer, comptime op: Op, dst: Vec, src: Rm) Error!void {
    if (comptime op.sse == .fma or op.sse == .avx2) @compileError("VEX-only op");
    if (dst.ymm or (src == .reg and src.reg.ymm)) return error.InvalidOperand;
    var o: Buf = .{};
    switch (op.pp) {
        1 => o.put(0x66),
        2 => o.put(0xf3),
        3 => o.put(0xf2),
        0 => {},
    }
    const xb = rexBits(src);
    const rex: u8 = (if (op.w) @as(u8, 8) else 0) | @as(u8, dst.id >> 3) << 2 | @as(u8, xb.x) << 1 | xb.b;
    if (rex != 0) o.put(0x40 | rex);
    o.put(0x0f);
    if (op.map == 2) o.put(0x38) else if (op.map == 3) o.put(0x3a);
    o.put(op.op);
    try modrm(&o, dst.id, src);
    return commit(cb, &o);
}

/// VEX: `op dst, src1, src2` (3-operand). For 2-operand ops (moves, broadcast) pass `src1 = null`.
/// `dst.ymm` selects VEX.L = 256.
pub fn vex(cb: *CodeBuffer, comptime op: Op, dst: Vec, src1: ?Vec, src2: Rm) Error!void {
    if (op.scalar != 0 and dst.ymm) return error.InvalidOperand;
    if (src1) |s| if (s.ymm != dst.ymm) return error.InvalidOperand;
    if (src2 == .reg and src2.reg.ymm != (dst.ymm and !op.src_xmm)) return error.InvalidOperand;
    if ((src1 == null) != op.two) return error.InvalidOperand;
    var s1 = src1;
    var s2 = src2;
    if (op.comm and op.map == 1 and !op.w and src2 == .reg and src2.reg.id >= 8 and src1.?.id < 8) {
        s1 = src2.reg;
        s2 = .{ .reg = src1.? };
    }
    var o: Buf = .{};
    const xb = rexBits(s2);
    const R: u8 = ~(dst.id >> 3) & 1;
    const vvvv: u8 = ~@as(u8, if (s1) |v| v.id else 0) & 0xf;
    const L: u8 = @intFromBool(dst.ymm);
    if (op.map == 1 and !op.w and xb.x == 0 and xb.b == 0) {
        o.put(0xc5);
        o.put(R << 7 | vvvv << 3 | L << 2 | op.pp);
    } else {
        o.put(0xc4);
        o.put(R << 7 | @as(u8, ~xb.x & 1) << 6 | @as(u8, ~xb.b & 1) << 5 | op.map);
        o.put(@as(u8, @intFromBool(op.w)) << 7 | vvvv << 3 | L << 2 | op.pp);
    }
    o.put(op.op);
    try modrm(&o, dst.id, s2);
    return commit(cb, &o);
}

/// `vzeroupper` (C5 F8 77): call before returning to SSE code after 256-bit AVX.
pub fn vzeroupper(cb: *CodeBuffer) Error!void {
    try cb.emitBytes(&.{ 0xc5, 0xf8, 0x77 });
}
